import {videoFileIdentity} from './video-file-identity.js';
const $=selector=>document.querySelector(selector),assert=(condition,message)=>{if(!condition)throw new Error(message);};
const frame=()=>new Promise(resolve=>requestAnimationFrame(resolve));
const CHUNK=1024*1024,ABC='sha256:ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad',EMPTY='sha256:e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855';
function finiteProgress(row){return Number.isFinite(row.loaded)&&Number.isFinite(row.total)&&Number.isFinite(row.ratio)&&row.loaded>=0&&row.loaded<=row.total&&row.ratio>=0&&row.ratio<=1;}
function display(row){$('#progress').value=row.ratio;$('#progress-label').textContent=`${row.loaded} / ${row.total} bytes (${(100*row.ratio).toFixed(1)}%)`;}
export async function runVideoFileIdentityChecks(){
  const started=performance.now(),checks=[],report={startedAt:new Date().toISOString(),checks,policy:{algorithm:'SHA-256',worker:'Dedicated local module Worker per call',chunkBytes:CHUNK,cache:'None',onlineRuntimeCalls:'None; local worker/module loading only'},scope:'Actual browser module Worker and original synthetic real Blob/File bytes through the public identity API. Not actual Video per-file preset save/recall/UI integration, large-library throughput, heap profiling, native file access or Serato equivalence.'};
  const check=async(name,run)=>{const evidence={};try{await run(evidence);checks.push({name,passed:true,evidence});}catch(error){checks.push({name,passed:false,evidence,error:error.message,stack:error.stack});}$('#status').textContent=`${checks.filter(c=>c.passed).length}/${checks.length} passed · ${name}`;$('#results').textContent=JSON.stringify(report,null,2);await frame();};
  let retryFile;
  await check('Actual module Worker hashes empty real Blob to the published SHA256 empty vector',async evidence=>{const progress=[];evidence.identity=await videoFileIdentity(new Blob([]),{onProgress:row=>{progress.push(row);display(row);}});evidence.progress=progress;assert(evidence.identity===EMPTY,'Empty digest differs.');assert(progress.length===1&&progress[0].loaded===0&&progress[0].total===0&&progress[0].ratio===1,'Empty progress is not finite completed data.');});
  await check('Actual module Worker hashes real File abc bytes to the published SHA256 vector',async evidence=>{const progress=[];evidence.identity=await videoFileIdentity(new File(['abc'],'original-abc.mp4',{type:'video/mp4'}),{onProgress:row=>{progress.push(row);display(row);}});evidence.progress=progress;assert(evidence.identity===ABC,'abc digest differs.');assert(progress.every(finiteProgress)&&progress.at(-1).loaded===3,'Real File progress malformed.');});
  await check('Actual Worker spans three1MiB boundaries and matches independent Node crypto oracle',async evidence=>{const bytes=Uint8Array.from({length:CHUNK*3+17},(_,i)=>(i*31+(i>>>8))%256),file=new File([bytes],'pattern-original.webm',{type:'video/webm'}),progress=[];evidence.identity=await videoFileIdentity(file,{onProgress:row=>{progress.push(row);display(row);}});evidence.progress=progress;evidence.oracle='Node22.23.2 node:crypto SHA256 over independently generated (i*31+(i>>>8))%256 bytes';assert(evidence.identity==='sha256:9664051a0fd2eb4094c198506f25e7e893e3e885e83b105799bc900027cacaa2','Multichunk digest differs from independent oracle.');assert(JSON.stringify(progress.map(row=>row.loaded))===JSON.stringify([0,CHUNK,2*CHUNK,3*CHUNK,3*CHUNK+17]),'Incremental progress boundaries differ.');assert(progress.every(finiteProgress)&&progress.every((row,i)=>!i||row.loaded>=progress[i-1].loaded),'Progress not finite/monotonic.');});
  await check('Renaming/retyping identical actual bytes retains identity; same-name changed bytes differ',async evidence=>{const first=new File(['abc'],'same.mp4',{type:'video/mp4',lastModified:1}),renamed=new File(['abc'],'renamed.mov',{type:'video/quicktime',lastModified:999}),changed=new File(['abd'],'same.mp4',{type:'video/mp4',lastModified:1});evidence.identities=await Promise.all([first,renamed,changed].map(file=>videoFileIdentity(file)));assert(evidence.identities[0]===ABC&&evidence.identities[1]===ABC&&evidence.identities[2]!==ABC,'Identity used file metadata or missed changed bytes.');});
  await check('Concurrent actual workers keep independent progress and identities',async evidence=>{const progress=[[],[]],files=[new File(['abc'],'parallel-a.mp4'),new File([''],'parallel-empty.mp4')];evidence.identities=await Promise.all(files.map((file,index)=>videoFileIdentity(file,{onProgress:row=>progress[index].push(row)})));evidence.progress=progress;assert(evidence.identities[0]===ABC&&evidence.identities[1]===EMPTY,'Concurrent identity ownership crossed.');assert(progress[0].every(row=>row.total===3)&&progress[1].every(row=>row.total===0),'Concurrent progress ownership crossed.');});
  await check('Mid-file abort rejects AbortError and produces no late progress or identity',async evidence=>{const block=new Uint8Array(CHUNK).fill(37);retryFile=new File(Array(16).fill(block),'abort-original.webm',{type:'video/webm'});const controller=new AbortController(),progress=[];let resolved=false,errorName;
    try{await videoFileIdentity(retryFile,{signal:controller.signal,onProgress:row=>{progress.push(row);display(row);if(row.loaded>=CHUNK)controller.abort();}});resolved=true;}catch(error){errorName=error.name;}
    const count=progress.length;await frame();await frame();Object.assign(evidence,{bytes:retryFile.size,progress,errorName,resolved,progressAfterTwoFrames:progress.length});assert(!resolved&&errorName==='AbortError','Mid-file abort returned identity or wrong failure.');assert(progress.some(row=>row.loaded===CHUNK)&&progress.at(-1).loaded<retryFile.size,'Abort did not exercise an actual partial read.');assert(progress.length===count,'Aborted owner received late progress.');
  });
  await check('Independent retry after abort completes with real finite progress',async evidence=>{assert(retryFile,'Abort fixture missing.');const progress=[];evidence.identity=await videoFileIdentity(retryFile,{onProgress:row=>{progress.push(row);display(row);}});evidence.progress=progress;assert(evidence.identity==='sha256:bd1eda8827d807160fc66132310745ffad795808e3d5030788e919376dd21cda','Retry digest differs from independent Node crypto16MiB/byte37 oracle.');assert(progress.length===17&&progress.at(-1).loaded===retryFile.size&&progress.at(-1).ratio===1&&progress.every(finiteProgress),'Retry progress did not reach the real final byte.');});
  await check('Pre-aborted actual API rejects before progress and never resolves an identity',async evidence=>{const controller=new AbortController();controller.abort();let callbacks=0;try{await videoFileIdentity(new File(['abc'],'preabort.mp4'),{signal:controller.signal,onProgress:()=>callbacks++});throw Error('Unexpected identity');}catch(error){evidence.name=error.name;assert(error.name==='AbortError','Pre-abort did not reject AbortError.');}evidence.callbacks=callbacks;assert(callbacks===0,'Pre-abort emitted progress.');});
  await check('Blob-looking objects and inherited Blob prototypes are rejected before worker work',async evidence=>{let fakeCalls=0;const failures=[];for(const fake of [{size:3,slice(){fakeCalls++;},arrayBuffer(){fakeCalls++;}},Object.create(Blob.prototype)]){try{await videoFileIdentity(fake);failures.push('resolved');}catch(error){failures.push(error.name);}}Object.assign(evidence,{failures,fakeCalls});assert(failures.every(name=>name==='TypeError')&&fakeCalls===0,'File brand accepted forged input or invoked fake reads.');});
  await check('Thrown progress callback rejects exactly that owner and subsequent actual Worker still succeeds',async evidence=>{let callbacks=0,name;try{await videoFileIdentity(new File(['abc'],'callback.mp4'),{onProgress(){callbacks++;throw Error('intentional caller failure');}});}catch(error){name=error.message;}await frame();evidence.error=name;evidence.callbacks=callbacks;evidence.retry=await videoFileIdentity(new File(['abc'],'callback-retry.mp4'));assert(name==='intentional caller failure'&&callbacks===1&&evidence.retry===ABC,'Callback failure leaked an owner or blocked retry.');});
  report.passed=checks.filter(c=>c.passed).length;report.failed=checks.filter(c=>!c.passed).length;report.durationMs=performance.now()-started;$('#results').textContent=JSON.stringify(report,null,2);$('#status').textContent=`${report.passed} passed / ${report.failed} failed`;return report;
}
$('#run').onclick=async()=>{$('#run').disabled=true;$('#status').textContent='Running actual local module Workers…';try{await runVideoFileIdentityChecks();}catch(error){$('#status').textContent='Harness failed';$('#results').textContent=error.stack;}finally{$('#run').disabled=false;}};
